"""Render an evaluation report (from ``training.evaluate``) as Markdown."""

from __future__ import annotations

from pathlib import Path
from typing import Any


def _f(v: Any, nd: int = 3) -> str:
    if v is None:
        return "n/a"
    if isinstance(v, float):
        return f"{v:.{nd}f}"
    return str(v)


def render_markdown(r: dict[str, Any]) -> str:
    ds, cv, ho = r["dataset"], r["cross_validation"], r["holdout"]
    prod = ho["production_calibrated"]
    lines = [
        "# Model evaluation report",
        "",
        "Generated by `python -m app.cli evaluate`. **All numbers below were produced by running the "
        "evaluation code on synthetic data** — they measure how well the models learn the simulator's "
        "degradation patterns, not real-world performance.",
        "",
        "## Dataset",
        f"- Fleet: {r.get('fleet_config', {})}",
        f"- Observations: {ds['rows']:,} (one per unit every 6 h), positives: {ds['positives']:,} "
        f"({ds['positive_rate']:.1%}), units: {ds['units']}",
        f"- Label: failure within the next {ds['horizon_days']} days; last {ds['horizon_days']} days "
        "dropped (censored).",
        "",
        "## Protocol",
        f"- Cross-validation: {r['protocol']['cv']}",
        f"- Holdout: {r['protocol']['holdout']} (cutoff {ho['cutoff']}, train {ho['train_rows']:,} rows, "
        f"test {ho['test_rows']:,} rows with {ho['test_positives']:,} positives)",
        "",
        "## Model comparison",
        "",
        "| Model | CV PR-AUC | CV ROC-AUC | CV best F1 | Holdout PR-AUC | Holdout ROC-AUC "
        "| Holdout recall @ precision≥0.5 |",
        "|---|---|---|---|---|---|---|",
    ]
    for name, m in cv.items():
        h = ho["models"].get(name, {})
        lines.append(
            f"| {name} | {_f(m['pr_auc']['mean'])} ± {_f(m['pr_auc']['std'])} | "
            f"{_f(m['roc_auc']['mean'])} ± {_f(m['roc_auc']['std'])} | "
            f"{_f(m['best_f1']['mean'])} ± {_f(m['best_f1']['std'])} | {_f(h.get('pr_auc'))} | "
            f"{_f(h.get('roc_auc'))} | {_f(h.get('recall_at_precision_50'))} |"
        )
    pos_rate = ho["test_positives"] / max(ho["test_rows"], 1)
    lines += [
        "",
        f"For reference, a random classifier's PR-AUC equals the positive rate (≈ {pos_rate:.3f} on the holdout).",
        "",
        f"## Production configuration: calibrated `{prod['algorithm']}`",
        f"Selected automatically by best mean cross-validated PR-AUC (`{r['production_algorithm']}`).",
        "",
        f"- Holdout PR-AUC {_f(prod['pr_auc'])}, ROC-AUC {_f(prod['roc_auc'])}",
        f"- Brier score {_f(prod['brier'], 4)} (predicting the base rate everywhere: "
        f"{_f(prod['brier_base_rate'], 4)}; lower is better)",
        "",
        "| Risk level | Threshold | Precision | Recall | Share of observations flagged |",
        "|---|---|---|---|---|",
    ]
    for t in prod["thresholds"]:
        lines.append(
            f"| {t['risk_level']} | ≥ {t['threshold']} | {_f(t['precision'])} | {_f(t['recall'])} | "
            f"{_f(t['flagged_share'])} |"
        )
    lt = prod["lead_time_at_high"]
    lines += [
        "",
        f"**Failure detection** (holdout, threshold = high): {lt['detected']} of {lt['failures']} failures "
        f"were flagged at least once in the {ds['horizon_days']} days before they happened "
        f"(detection rate {_f(lt['detection_rate'])}); median warning {_f(lt['median_lead_days'], 1)} days.",
        "",
        "### Calibration (holdout)",
        "| Predicted bin | Count | Mean predicted | Observed failure rate |",
        "|---|---|---|---|",
    ]
    for b in prod["reliability"]:
        lines.append(
            f"| {b['bin_low']:.1f}–{b['bin_high']:.1f} | {b['count']} | {_f(b['mean_predicted'])} | "
            f"{_f(b['observed_rate'])} |"
        )
    lines += [
        "",
        "### Most influential features (mean |SHAP|, holdout)",
        "",
        "| Feature | Mean abs. SHAP |",
        "|---|---|",
    ]
    for g in ho["global_importance"]:
        lines.append(f"| `{g['feature']}` | {_f(g['mean_abs_shap'])} |")
    rul = r["rul"]
    lines += ["", "## Remaining useful life (RUL) regression", ""]
    if "mae_days" in rul:
        lines += [
            f"Rows within 60 days of a known failure; holdout rows: {rul['test_rows']:,}.",
            f"- MAE {_f(rul['mae_days'], 1)} days, RMSE {_f(rul['rmse_days'], 1)} days "
            f"(baseline 'always predict the median': MAE {_f(rul['baseline_median_mae_days'], 1)} days)",
            f"- MAE in the final 14 days before failure: {_f(rul['mae_days_last_14d'], 1)} days",
        ]
    else:
        lines.append(rul.get("note", "n/a"))
    lines += [
        "",
        "## Anomaly detection",
        f"Isolation Forest trained on healthy periods. ROC-AUC of the anomaly score against 'failure within "
        f"horizon' on the holdout: {_f(r['anomaly']['roc_auc_vs_failure_within_horizon'])}. The anomaly score "
        "flags unusual behaviour; it is not a failure prediction.",
        "",
        "## Limitations",
        "- Synthetic data: real equipment has more failure modes, sensor faults and operating regimes.",
        "- Few failures per unit; metrics have real variance (see ± std across folds).",
        "- Hyper-parameters are fixed sensible defaults, not tuned; tuning would require nested CV.",
        "- RUL is trained only on rows with a known upcoming failure (right-censoring ignored).",
        "",
        f"_Elapsed {r['elapsed_seconds']} s · libraries {r['library_versions']}_",
    ]
    return "\n".join(lines) + "\n"


def write_markdown(report: dict[str, Any], path: Path) -> None:
    path.write_text(render_markdown(report))
